#pragma STDC FENV_ACCESS ON

struct Number{mpfr_t x;explicit Number(mpfr_prec_t p){mpfr_init2(x,p);}~Number(){mpfr_clear(x);}Number(const Number&)=delete;Number&operator=(const Number&)=delete;};
struct Manifest{int K=0,vector_bits=0,ac_bits=0,cutoff_power10=0;uint64_t cutoff=0,segment_size=0,total_segments=0;std::string vector_sha,normalization_sha,parameter_sha,carrier_num,carrier_den;std::vector<std::string> are,aim;};
static Manifest read_manifest(const std::string&path){std::ifstream in(path);if(!in)throw std::runtime_error("cannot open manifest");std::string magic;in>>magic;if(magic!="RIEMANN_D0801_AUTOCORRELATION_V1")throw std::runtime_error("bad manifest magic");Manifest m;std::string key;int n=0;while(in>>key){if(key=="cells")in>>m.K;else if(key=="vector_scale_bits")in>>m.vector_bits;else if(key=="autocorr_scale_bits")in>>m.ac_bits;else if(key=="vector_sha256")in>>m.vector_sha;else if(key=="normalization_sha256")in>>m.normalization_sha;else if(key=="parameter_sha256")in>>m.parameter_sha;else if(key=="cutoff_power10")in>>m.cutoff_power10;else if(key=="cutoff")in>>m.cutoff;else if(key=="carrier_num")in>>m.carrier_num;else if(key=="carrier_den")in>>m.carrier_den;else if(key=="segment_size")in>>m.segment_size;else if(key=="total_segments")in>>m.total_segments;else if(key=="a_count"){in>>n;m.are.resize(n);m.aim.resize(n);}else if(key=="a"){int d;in>>d;if(d<0||d>=n)throw std::runtime_error("bad autocorrelation index");in>>m.are[d]>>m.aim[d];}else throw std::runtime_error("unknown manifest key: "+key);}if(m.K<1||n!=m.K+1||m.cutoff<2||m.carrier_den=="0")throw std::runtime_error("incomplete manifest");uint64_t p10=1;for(int i=0;i<m.cutoff_power10;i++){if(p10>UINT64_MAX/10)throw std::runtime_error("cutoff overflow");p10*=10;}if(p10!=m.cutoff)throw std::runtime_error("cutoff mismatch");if((m.cutoff-2)/m.segment_size+1!=m.total_segments)throw std::runtime_error("segment mismatch");return m;}
static std::vector<uint32_t> simple_primes(uint64_t n){std::vector<uint8_t>a(n+1,1);a[0]=0;if(n>=1)a[1]=0;for(uint64_t p=2;p*p<=n;p++)if(a[p])for(uint64_t k=p*p;k<=n;k+=p)a[k]=0;std::vector<uint32_t>o;for(uint64_t p=2;p<=n;p++)if(a[p])o.push_back((uint32_t)p);return o;}
static std::vector<uint64_t> segment_primes(uint64_t low,uint64_t high,const std::vector<uint32_t>&base){std::vector<uint8_t>a(high-low,1);uint64_t root=(uint64_t)sqrtl((long double)(high-1));while((root+1)*(root+1)<=high-1)++root;while(root*root>high-1)--root;for(uint32_t p:base){if(p>root)break;uint64_t st=std::max<uint64_t>((uint64_t)p*p,((low+p-1)/p)*p);for(uint64_t k=st;k<high;k+=p)a[k-low]=0;}std::vector<uint64_t>o;for(uint64_t i=0;i<high-low;i++)if(a[i]&&low+i>=2)o.push_back(low+i);return o;}
struct Pairwise{long double v[64]{};bool used[64]{};uint64_t count=0;void add(long double x){count++;for(int i=0;i<64;i++){if(!used[i]){v[i]=x;used[i]=true;return;}x=v[i]+x;used[i]=false;}throw std::runtime_error("pairwise overflow");}long double finish()const{long double x=0;for(int i=0;i<64;i++)if(used[i])x=x+v[i];return x;}};
static std::string zstr(const mpz_t z){char*r=mpz_get_str(nullptr,10,z);std::string s(r);void(*f)(void*,size_t);mp_get_memory_functions(nullptr,nullptr,&f);f(r,s.size()+1);return s;}
static std::pair<std::string,std::string> exact_ld(long double x){mpfr_t t;mpfr_init2(t,64);mpfr_set_ld(t,x,MPFR_RNDN);mpz_t z,d;mpz_init(z);mpz_init_set_ui(d,1);mpfr_exp_t e=mpfr_get_z_2exp(z,t);if(e>=0)mpz_mul_2exp(z,z,e);else mpz_mul_2exp(d,d,-e);auto out=std::make_pair(zstr(z),zstr(d));mpz_clear(z);mpz_clear(d);mpfr_clear(t);return out;}
struct FastEval{
 const Manifest&m;mpfr_prec_t prec;int K,M;long double pi,L,Tld;__float128 piq,Tq;std::vector<long double> ar,ai,rr,ri;std::vector<uint32_t>base;uint64_t phase_boundary_near=0,support_boundary_near=0;long double min_phase_boundary=1,min_support_boundary=1;
 FastEval(const Manifest&mm,mpfr_prec_t p,int grid):m(mm),prec(p),K(mm.K),M(grid),ar(K+1),ai(K+1),rr(M),ri(M){
  if(FLT_RADIX!=2||LDBL_MANT_DIG!=64||sizeof(long double)!=16)throw std::runtime_error("requires x86 binary80 long double ABI");if(fegetround()!=FE_TONEAREST)throw std::runtime_error("requires FE_TONEAREST");
  Number x(p),y(p),z(p);mpfr_const_pi(x.x,MPFR_RNDN);pi=mpfr_get_ld(x.x,MPFR_RNDN);piq=mpfr_get_float128(x.x,MPFR_RNDN);mpfr_set_ui(x.x,m.cutoff,MPFR_RNDN);mpfr_log(x.x,x.x,MPFR_RNDN);L=mpfr_get_ld(x.x,MPFR_RNDN);
  mpz_t zn,zd;mpz_init_set_str(zn,m.carrier_num.c_str(),10);mpz_init_set_str(zd,m.carrier_den.c_str(),10);mpfr_set_z(x.x,zn,MPFR_RNDN);mpfr_set_z(y.x,zd,MPFR_RNDN);mpfr_div(x.x,x.x,y.x,MPFR_RNDN);Tld=mpfr_get_ld(x.x,MPFR_RNDN);Tq=mpfr_get_float128(x.x,MPFR_RNDN);mpz_clear(zn);mpz_clear(zd);
  for(int d=0;d<=K;d++){mpz_t a;mpz_init(a);mpz_set_str(a,m.are[d].c_str(),10);mpfr_set_z(x.x,a,MPFR_RNDN);mpfr_div_2ui(x.x,x.x,m.ac_bits,MPFR_RNDN);ar[d]=mpfr_get_ld(x.x,MPFR_RNDN);mpz_set_str(a,m.aim[d].c_str(),10);mpfr_set_z(x.x,a,MPFR_RNDN);mpfr_div_2ui(x.x,x.x,m.ac_bits,MPFR_RNDN);ai[d]=mpfr_get_ld(x.x,MPFR_RNDN);mpz_clear(a);}for(int j=0;j<M;j++){mpfr_const_pi(x.x,MPFR_RNDN);mpfr_mul_ui(x.x,x.x,2*(unsigned long)j,MPFR_RNDN);mpfr_div_ui(x.x,x.x,M,MPFR_RNDN);mpfr_sin_cos(y.x,z.x,x.x,MPFR_RNDN);rr[j]=mpfr_get_ld(z.x,MPFR_RNDN);ri[j]=-mpfr_get_ld(y.x,MPFR_RNDN);}base=simple_primes((uint64_t)sqrtl((long double)m.cutoff)+1);
 }
 struct Seg{uint64_t mid;long double lm,ism;long long k0;__float128 cres;};
 Seg setup(uint64_t low,uint64_t high){Seg s{};s.mid=low+(high-low)/2;Number x(prec),y(prec),z(prec),w(prec);mpfr_set_ui(x.x,s.mid,MPFR_RNDN);mpfr_log(y.x,x.x,MPFR_RNDN);s.lm=mpfr_get_ld(y.x,MPFR_RNDN);mpfr_sqrt(z.x,x.x,MPFR_RNDN);mpfr_ui_div(z.x,1,z.x,MPFR_RNDN);s.ism=mpfr_get_ld(z.x,MPFR_RNDN);mpfr_set_float128(x.x,Tq,MPFR_RNDN);mpfr_mul(y.x,x.x,y.x,MPFR_RNDN);mpfr_const_pi(z.x,MPFR_RNDN);mpfr_mul_ui(w.x,y.x,M,MPFR_RNDN);mpfr_mul_ui(z.x,z.x,2,MPFR_RNDN);mpfr_div(w.x,w.x,z.x,MPFR_RNDN);s.k0=mpfr_get_si(w.x,MPFR_RNDN);mpfr_const_pi(z.x,MPFR_RNDN);mpfr_mul_si(z.x,z.x,2*s.k0,MPFR_RNDN);mpfr_div_ui(z.x,z.x,M,MPFR_RNDN);mpfr_sub(y.x,y.x,z.x,MPFR_RNDN);s.cres=mpfr_get_float128(y.x,MPFR_RNDN);return s;}
 long double term(uint64_t q,const Seg&s){long double z=(long double)((int64_t)q-(int64_t)s.mid)/(long double)(q+s.mid),z2=z*z,p=z,dl=0;for(int j=0;j<4;j++){dl+=2*p/(2*j+1);p*=z2;}long double y=(long double)((int64_t)q-(int64_t)s.mid)/(long double)s.mid,yp=1,pol=1;const long double c[5]={-0.5L,3.0L/8,-5.0L/16,35.0L/128,-63.0L/256};for(int j=0;j<5;j++){yp*=y;pol+=c[j]*yp;}long double lq=s.lm+dl,is=s.ism*pol,amp=lq*is/pi,r=K*lq/L;long d=(long)floorl(r);long double f=r-d;if(d<0)d=0;if(d>=K)return 0;long double dist=fminl(fabsl(f),fabsl(1-f));min_support_boundary=fminl(min_support_boundary,dist);if(dist<0x1p-35L)support_boundary_near++;long double rre=ar[d]+f*(ar[d+1]-ar[d]),rim=ai[d]+f*(ai[d+1]-ai[d]);__float128 zq=(__float128)((int64_t)q-(int64_t)s.mid)/(__float128)(q+s.mid),zq2=zq*zq,pq=zq,dlq=0;for(int j=0;j<4;j++){dlq+=2*pq/(2*j+1);pq*=zq2;}__float128 total=s.cres+Tq*dlq,scaled=M*total/(2*piq);long long k=llroundq(scaled);__float128 deltaq=total-2*piq*k/M;long double bd=(long double)(piq/M-fabsq(deltaq));min_phase_boundary=fminl(min_phase_boundary,bd);if(bd<0x1p-55L)phase_boundary_near++;long double de=(long double)deltaq,d2=de*de,tr=1-d2/2,ti=-de+d2*de/6;int j=(int)((s.k0+k)%M);if(j<0)j+=M;long double er=rr[j]*tr-ri[j]*ti,ei=rr[j]*ti+ri[j]*tr;return amp*(er*rre-ei*rim);}
};
int main(int argc,char**argv){try{std::map<std::string,std::string>o;for(int i=1;i<argc;i++){std::string a=argv[i];if(a.rfind("--",0)==0&&i+1<argc)o[a]=argv[++i];else throw std::runtime_error("bad argument "+a);}auto req=[&](const std::string&k){if(!o.count(k))throw std::runtime_error("missing "+k);return o[k];};Manifest m=read_manifest(req("--manifest"));uint64_t start=stoull(req("--start-segment")),end=stoull(req("--end-segment"));int grid=o.count("--phase-grid")?stoi(o["--phase-grid"]):32768;mpfr_prec_t p=o.count("--setup-precision")?stol(o["--setup-precision"]):192;if(!(start<end&&end<=m.total_segments))throw std::runtime_error("bad range");fesetround(FE_TONEAREST);FastEval ev(m,p,grid);Pairwise sum,abssum;uint64_t pc=0;for(uint64_t sg=start;sg<end;sg++){uint64_t low=2+sg*m.segment_size,high=std::min<uint64_t>(m.cutoff+1,low+m.segment_size);auto ss=ev.setup(low,high);auto ps=segment_primes(low,high,ev.base);for(uint64_t q:ps){long double t=ev.term(q,ss);sum.add(t);abssum.add(fabsl(t));}pc+=ps.size();}long double mid=sum.finish(),av=abssum.finish();auto mr=exact_ld(mid),ar=exact_ld(av);std::ofstream out(req("--output"));out<<"{\n  \"schema\": \"riemann.piecewise-carrier-fast-midpoint-shard.v1\",\n  \"segment_start\": "<<start<<", \"segment_end\": "<<end<<",\n  \"prime_count\": "<<pc<<", \"total_terms\": "<<pc<<", \"include_higher_powers\": false,\n  \"vector_sha256\": \""<<m.vector_sha<<"\", \"parameter_sha256\": \""<<m.parameter_sha<<"\", \"normalization_sha256\": \""<<m.normalization_sha<<"\",\n  \"phase_grid_M\": "<<grid<<", \"phase_taylor_R\": 3, \"log_series_J\": 3, \"sqrt_series_J\": 5,\n  \"setup_precision_bits\": "<<p<<", \"mpfr_version\": \""<<mpfr_get_version()<<"\",\n  \"arithmetic_contract\": \"binary80 nearest basic arithmetic, binary128 phase arithmetic, MPFR setup, balanced pairwise summation; global moat required\",\n  \"midpoint_rayleigh\": {\"numerator\": "<<mr.first<<", \"denominator\": "<<mr.second<<"},\n  \"absolute_term_sum_midpoint\": {\"numerator\": "<<ar.first<<", \"denominator\": "<<ar.second<<"},\n  \"phase_boundary_near_count\": "<<ev.phase_boundary_near<<", \"support_boundary_near_count\": "<<ev.support_boundary_near<<",\n  \"minimum_phase_boundary_distance\": \""<<std::setprecision(21)<<ev.min_phase_boundary<<"\", \"minimum_support_boundary_distance\": \""<<ev.min_support_boundary<<"\"\n}\n";}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<"\n";return 2;}return 0;}
